  values ('ME', 'short_answer', 'What are the prospects for floriculture in Bhutan?', 'Bhutan''s varied climates (subtropical south to temperate and alpine north), clean environment and rich native flora (orchids, rhododendrons, primulas, blue poppy) suit many flowers - cut flowers like roses, gerberas, carnations, lilies, chrysanthemums and orchids, and bulbs. Demand is growing for religious offerings, festivals (tshechus), weddings, hotels and tourism, events and urban landscaping (including GMC); most cut flowers are now imported from India, so domestic production can replace imports and save foreign exchange; organic and niche products (orchids, bulbs, seeds) have export potential. Floriculture gives high income per unit area and jobs for youth and women, especially in greenhouses near towns. Challenges to address: cold chain and transport, quality planting material, technical skills, market linkages and small scale - but with government support and protected cultivation the prospects are good.', null, '[{"point": "Favourable agro-climatic diversity (subtropical to alpine), clean environment, native flora (orchids, rhododendrons, blue poppy)", "marks": 1.5}, {"point": "Market: domestic demand (religious offerings, festivals, weddings, hotels, tourism, GMC), import substitution (flowers imported from India), export potential", "marks": 1.5}, {"point": "Opportunities: income/ employment for youth and women, protected cultivation, value chain (bulbs, seeds), government support; challenges briefly (cold chain, transport, skills)", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'subject-specialisation') and t.slug = 'beautification-officer'), (select id from public.exam_papers where code = 'me-technical-3'), 'standard', 5,
    540, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (Technical, Beautification Officer): BCSE 2024 - check flagged answer keys before publishing", "source": {"title": "BCSE 2024 Main Examination, Technical Paper III, Beautification Officer", "year": 2024, "url": "https://rcsc.gov.bt/technical-paper-iii/"}}'::jsonb, null, null, null, null, (select id from public.specialisations where code = 'beautification-officer'), null)
