  values ('ME', 'short_answer', 'As a Beautification Officer, how would you promote urban gardening?', 'Raise awareness of the benefits (beauty, fresh food, mental well-being, cleaner air) through campaigns and social media; run training and demonstrations on container, balcony, rooftop and vertical gardening, composting and rainwater use; set up demonstration and community gardens in public spaces, schools, institutions and dzong premises; supply seedlings, seeds and pots at low cost through nurseries; organise competitions and awards for the best gardens and cleanest neighbourhoods; work with the thromde, Ministry of Agriculture and Livestock, schools, NGOs and businesses (sponsorship); encourage building regulations that include green spaces and roof gardens; and monitor and maintain public plantings.', null, '[{"point": "Awareness and training (workshops, demonstrations), community/ school gardens", "marks": 1.5}, {"point": "Space strategies: rooftop, balcony, vertical, container gardening, public spaces, allotments", "marks": 1.5}, {"point": "Support: seedlings/ inputs, competitions/ awards, partnerships with thromde, MoAL, schools, private sector, policy incentives, composting/ rainwater", "marks": 2}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
