  values ('ME', 'short_answer', 'From a Buddhist point of view, why is offering flowers to the Könchog Sum (Triple Gem) considered an act of generosity?', 'Generosity (jinpa, dana) is the first of the six perfections (paramitas). Offering flowers to the Könchog Sum - the Buddha, Dharma and Sangha - is giving something beautiful without expecting anything in return, so it trains the mind to let go of attachment and miserliness. Flowers are among the traditional outer offerings (with water, incense, light, food and music); offering them with devotion accumulates merit, purifies negative karma and develops respect and faith in the Triple Gem. As the flowers fade, they also remind the giver of impermanence (anicca), supporting wisdom alongside generosity.', null, '[{"point": "Generosity (jinpa/ dana) as first paramita - giving without attachment to the Buddha, Dharma, Sangha", "marks": 2}, {"point": "Flowers as one of the outer offerings; offering accumulates merit, purifies mind, counters attachment/ miserliness, expresses devotion; impermanence reflection", "marks": 3}]'::jsonb, (select id from public.subjects where slug = 'subject-specialisation'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'subject-specialisation') and t.slug = 'beautification-officer'), (select id from public.exam_papers where code = 'me-technical-3'), 'standard', 5,
    540, 'historical_official', 'awaiting_review',
    null, null,
    '{"verdict": "pass", "issues": [], "checker_notes": "Model answer, marking guide and rubric written by Claude from the RCSC paper; facts were checked against what is widely published, but please read before publishing. Real past-paper questions keep RCSC wording.", "batch": "ME Paper III (Technical, Beautification Officer): BCSE 2024 - check flagged answer keys before publishing", "source": {"title": "BCSE 2024 Main Examination, Technical Paper III, Beautification Officer", "year": 2024, "url": "https://rcsc.gov.bt/technical-paper-iii/"}}'::jsonb, null, null, null, null, (select id from public.specialisations where code = 'beautification-officer'), null)
